-- Auto-generated dump of quiz questions
-- Safe to re-run: uses CREATE TABLE IF NOT EXISTS and INSERT OR IGNORE

CREATE TABLE IF NOT EXISTS questions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    topic TEXT NOT NULL,
    difficulty TEXT NOT NULL,
    question TEXT NOT NULL,
    answer TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(question)
);

INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('C# essentials', 'Сложно', 'Чем отличается poor man''s pattern matching через `is`/`switch` expressions от boxing struct-типов при использовании `object` в качестве параметра, и как избежать лишнего boxing при паттерн-матчинге по значимым типам в C#?', 'При сравнении struct через `is` с типом (например, `obj is int i`) происходит unboxing, а не boxing, если `obj` уже упакован; но если значимый тип передаётся как `object` изначально — boxing уже произошёл при присвоении. Избежать boxing можно через generics с ограничением `where T : struct` или через `Span<T>`/паттерны с ref struct, не допускающие приведения к `object`.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('C# essentials', 'Сложно', 'Объясните, почему `async void` методы считаются антипаттерном, и опишите два конкретных сценария, где необработанное исключение в таком методе приведёт к падению процесса, минуя обычный try/catch вызывающего кода.', '`async void` не возвращает Task, поэтому исключения не могут быть перехвачены вызывающей стороной через await; они попадают в SynchronizationContext (например, в UI-потоке) и приводят к необработанному исключению уровня приложения. Сценарии: 1) обработчик события кнопки в WPF, кидающий исключение в асинхронном коде — приложение крашится; 2) `async void` метод, вызванный из ThreadPool без SynchronizationContext — исключение уходит в AppDomain.UnhandledException и завершает процесс.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('.NET CORE', 'Сложно', 'Опишите порядок выполнения middleware в ASP.NET Core pipeline при наличии `UseExceptionHandler`, `UseRouting`, `UseAuthentication`, `UseAuthorization` и `UseEndpoints`, и объясните, почему порядок регистрации критичен для корректной обработки ошибок авторизации.', 'Middleware выполняется в порядке регистрации по принципу ''матрёшки'' (вложенные вызовы next()). `UseExceptionHandler` должен быть первым, чтобы перехватывать исключения из всех последующих middleware. `UseRouting` определяет endpoint до `UseAuthentication`/`UseAuthorization`, так как авторизация нуждается в информации о endpoint (атрибутах `[Authorize]`). Если `UseAuthorization` поставить перед `UseRouting`, endpoint ещё не определён и авторизация не сможет проверить требуемые политики, что приведёт к ошибке или пропуску проверки.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('.NET CORE', 'Сложно', 'В чём разница между Scoped, Singleton и Transient временем жизни в DI-контейнере .NET, и какая проблема возникает при внедрении Scoped-сервиса в Singleton, и как её решить через `IServiceScopeFactory`?', 'Singleton живёт всё время жизни приложения, Scoped — в рамках одного HTTP-запроса (или scope), Transient создаётся при каждом запросе экземпляра. При внедрении Scoped в Singleton происходит ''captive dependency'' — Scoped-сервис захватывается на весь жизненный цикл Singleton и никогда не освобождается корректно, что может привести к утечкам данных между запросами (например, DbContext). Решение — не внедрять Scoped напрямую, а внедрить `IServiceScopeFactory`, создавать scope вручную (`CreateScope()`) и резолвить сервис внутри него при каждом использовании.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('SQL', 'Сложно', 'Объясните разницу между уровнями изоляции транзакций Read Committed и Repeatable Read в PostgreSQL, и опишите, какую аномалию (phantom read) допускает первый уровень, но не допускает второй, приведя конкретный пример с двумя параллельными транзакциями.', 'Read Committed видит только зафиксированные данные на момент каждого отдельного запроса внутри транзакции, поэтому повторный SELECT в той же транзакции может увидеть новые строки, вставленные другой зафиксированной транзакцией (phantom read). Repeatable Read фиксирует снимок данных на начало транзакции и не видит изменений, сделанных другими транзакциями после этого момента, что предотвращает phantom read в PostgreSQL (за счёт MVCC snapshot isolation). Пример: Транзакция A делает `SELECT COUNT(*) FROM orders WHERE status=''new''`, получает 5; Транзакция B вставляет новый заказ со статусом ''new'' и коммитит; при Read Committed повторный SELECT в A вернёт 6, при Repeatable Read — по-прежнему 5.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('SQL', 'Сложно', 'Как работает индекс типа B-Tree при выполнении запроса с условием `WHERE column LIKE ''abc%''` против `WHERE column LIKE ''%abc''`, и почему второй случай не использует индекс эффективно?', 'B-Tree индекс хранит значения в отсортированном порядке, поэтому префиксный поиск (`''abc%''`) может использовать индекс для быстрого поиска диапазона, начинающегося с ''abc''. Поиск с ведущим wildcard (`''%abc''`) не может использовать сортировку индекса, так как совпадение может начинаться в любой позиции строки — движок вынужден сканировать все значения (full scan) или использовать специальные индексы (например, GIN с триграммами в PostgreSQL) для эффективного поиска подстрок.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('ORM', 'Сложно', 'Опишите проблему N+1 запросов при использовании Entity Framework Core с ленивой загрузкой (lazy loading) навигационных свойств, и покажите два альтернативных подхода для её решения на уровне LINQ-запроса.', 'Проблема N+1: при загрузке коллекции из N сущностей и последующем обращении к навигационному свойству каждой из них при lazy loading выполняется 1 запрос на список плюс N дополнительных запросов для каждой связанной сущности. Решения: 1) Eager loading через `.Include()`/`.ThenInclude()`, что объединяет данные в один SQL-запрос через JOIN; 2) Explicit loading через `.Entry(entity).Collection(...).Load()` с батчингом, либо проекция через `.Select()` сразу в DTO, что генерирует один оптимизированный запрос без загрузки лишних данных.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('Databases', 'Сложно', 'В MongoDB объясните, как работает шардирование (sharding) по хэш-ключу против диапазонного шардирования (range-based), и какие проблемы диапазонного шардирования решает хэш-подход применительно к ''hotspot'' шардам при последовательно возрастающих ключах (например, ObjectId по времени).', 'При диапазонном шардировании документы с близкими значениями shard key (например, монотонно возрастающий ObjectId) попадают в один и тот же шард, создавая ''горячий'' шард, на который приходится вся нагрузка записи, в то время как остальные шарды простаивают. Хэш-шардирование применяет хэш-функцию к shard key перед распределением, равномерно рассеивая последовательные значения по разным шардам, что устраняет hotspot, но ухудшает эффективность range-запросов, поскольку соседние по значению документы физически разбросаны по разным шардам.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('Architecture', 'Сложно', 'Сравните Vertical Slice Architecture с классической Onion (луковичной) архитектурой: в чём принципиальное отличие в организации кода по фичам против организации по слоям, и какие компромиссы (trade-offs) это создаёт при росте команды и кодовой базы?', 'Onion-архитектура организует код по техническим слоям (Domain, Application, Infrastructure, Presentation), обеспечивая строгую инверсию зависимостей к центру, но при добавлении новой фичи требует изменений сразу в нескольких слоях/проектах, что увеличивает связность на уровне фичи. Vertical Slice организует код по фичам — каждая фича (например, через MediatR handler) содержит всю необходимую логику от запроса до ответа в одном месте, снижая межфайловую навигацию и облегчая независимую разработку фич разными командами, но может привести к дублированию логики между срезами и усложнить переиспользование общих доменных правил без дисциплины по вынесению общего кода в shared kernel.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('DesignPatterns', 'Сложно', 'Объясните разницу между паттернами Factory Method и Abstract Factory, и приведите сценарий, где использование Abstract Factory необходимо, а простого Factory Method недостаточно.', 'Factory Method определяет один метод для создания одного типа продукта, делегируя выбор конкретной реализации подклассам через переопределение метода. Abstract Factory предоставляет интерфейс для создания семейств связанных объектов без указания их конкретных классов, координируя создание нескольких взаимосвязанных продуктов. Сценарий: кроссплатформенный UI-toolkit, где нужно создавать согласованные наборы виджетов (Button, Checkbox, Scrollbar) для Windows или macOS — Abstract Factory гарантирует, что все созданные виджеты принадлежат одной теме/платформе, чего Factory Method, создающий объекты по одному, обеспечить не может.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('Tests', 'Сложно', 'Опишите разницу между Fake, Mock и Stub в контексте unit-тестирования, и объясните, почему чрезмерное использование Mock-объектов может привести к хрупким тестам (brittle tests), тесно связанным с деталями реализации.', 'Stub возвращает заранее заданные ответы на вызовы без проверки взаимодействий; Mock, помимо предоставления ответов, верифицирует сами вызовы (например, что метод был вызван ровно один раз с определёнными аргументами); Fake — это упрощённая рабочая реализация (например, in-memory база данных вместо реальной). Чрезмерное использование Mock приводит к тестам, которые проверяют не поведение системы, а конкретные внутренние вызовы методов — при рефакторинге внутренней реализации (без изменения наблюдаемого поведения) такие тесты начинают падать, хотя система работает корректно, что называется overspecification и снижает ценность тестов как страховки от регрессий.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('API', 'Сложно', 'В чём разница между REST и gRPC с точки зрения контракта, сериализации и производительности, и почему gRPC плохо подходит для публичных API, потребляемых напрямую браузером без прокси-слоя?', 'REST обычно использует JSON поверх HTTP/1.1 с человекочитаемым, слабо типизированным контрактом (или OpenAPI-описанием), а gRPC использует Protocol Buffers (бинарная сериализация) поверх HTTP/2 со строго типизированным .proto контрактом, обеспечивая меньший размер payload и поддержку потоковой передачи (streaming) в обе стороны. gRPC плохо подходит для браузеров напрямую, потому что браузерный fetch/XHR API не даёт полного контроля над HTTP/2 фреймами, необходимыми для gRPC (trailers, специфичный формат сообщений), поэтому требуется gRPC-Web с прокси-транскодером (например, Envoy), преобразующим запросы в совместимый с браузером формат.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('AI', 'Сложно', 'Объясните, что такое RAG (Retrieval-Augmented Generation) в контексте использования больших языковых моделей, и почему простое увеличение размера контекстного окна модели не решает полностью проблему, которую решает RAG.', 'RAG — это архитектурный подход, при котором перед генерацией ответа языковой моделью выполняется поиск релевантных фрагментов из внешней базы знаний (обычно через векторное сходство embedding-ов), и найденные фрагменты добавляются в промпт как контекст. Увеличение контекстного окна не решает полностью проблему RAG, потому что: 1) стоимость и задержка растут с размером контекста; 2) модели демонстрируют деградацию точности при работе с очень длинным контекстом (''lost in the middle''); 3) RAG позволяет обновлять базу знаний без переобучения или передачи всего корпуса данных в каждый запрос, обеспечивая актуальность и меньшую стоимость на каждый вызов.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('git', 'Сложно', 'Объясните разницу между `git rebase` и `git merge` с точки зрения истории коммитов, и опишите проблему, которая возникает при rebase уже запушенной в общий репозиторий ветки, над которой работают другие разработчики.', '`git merge` создаёт новый merge-коммит, сохраняя исходную историю обеих веток без изменений, тогда как `git rebase` переписывает историю, применяя коммиты текущей ветки поверх новой базовой точки, создавая новые SHA для каждого коммита. Rebase уже запушенной публичной ветки — опасен, потому что переписывает существующие коммиты новыми хэшами; у других разработчиков, уже имеющих старую версию ветки, при следующем pull возникнут дублирующиеся или расходящиеся истории (diverged branches), что потребует принудительного `push --force` и может привести к потере чужих незапушенных изменений или сложным конфликтам при слиянии.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('Docker', 'Сложно', 'Опишите разницу между multi-stage builds в Dockerfile и обычной однослойной сборкой, и объясните, как multi-stage build помогает уменьшить размер финального образа для .NET-приложения, скомпилированного из исходников.', 'В обычной однослойной сборке все инструменты сборки (SDK, компиляторы, зависимости для сборки) остаются в финальном образе, значительно увеличивая его размер. Multi-stage build использует несколько `FROM` секций: первая стадия (на основе полного SDK-образа) компилирует и публикует приложение, а финальная стадия начинается с легковесного runtime-образа (например, `aspnet` вместо `sdk`), в который через `COPY --from=build` копируются только скомпилированные артефакты, что исключает SDK, исходный код и промежуточные файлы сборки из итогового образа, существенно уменьшая его размер и площадь атаки.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('Linux', 'Сложно', 'Объясните разницу между жёсткими (hard link) и символическими (symbolic link) ссылками в файловой системе Linux, и опишите, что произойдёт с каждым типом ссылки при удалении оригинального файла, а также ограничение hard link, связанное с файловыми системами и inode.', 'Hard link указывает непосредственно на тот же inode, что и оригинальный файл, поэтому оба имени равноправны — удаление ''оригинала'' лишь уменьшает счётчик ссылок на inode, а данные остаются доступны через hard link, пока счётчик не станет равным нулю. Symbolic link — это отдельный файл, содержащий путь к целевому файлу; при удалении оригинала symlink остаётся, но становится ''битым'' (dangling), указывая на несуществующий путь. Ограничение hard link: он не может пересекать границы файловых систем (разных разделов/точек монтирования), так как inode уникальны только в рамках одной файловой системы, и обычно не может ссылаться на директории (во избежание циклов в файловой иерархии).');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('DataStructures', 'Сложно', 'Объясните, почему `HashSet<T>` в .NET в среднем случае обеспечивает O(1) для операций Add/Contains, но в худшем случае деградирует до O(n), и как параметр `LoadFactor` и стратегия рехеширования влияют на эту деградацию.', '`HashSet<T>` использует хэш-таблицу с цепочками (chaining) для разрешения коллизий: хэш-функция определяет корзину (bucket) для элемента, и в среднем случае при хорошем распределении хэшей каждая корзина содержит O(1) элементов, обеспечивая константное время доступа. В худшем случае (например, при плохой хэш-функции или намеренной атаке hash flooding), множество элементов попадает в одну корзину, превращая поиск в линейный перебор связного списка — O(n). Load Factor (отношение количества элементов к числу корзин) контролирует, когда происходит рехеширование (увеличение количества корзин и перераспределение элементов); поддержание низкого Load Factor снижает вероятность длинных цепочек, но не устраняет теоретический худший случай полностью.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('Algoritms', 'Сложно', 'Сравните временную сложность QuickSort и MergeSort в среднем и худшем случаях, и объясните, почему QuickSort, несмотря на худший случай O(n²), часто предпочитается на практике по сравнению с гарантированным O(n log n) у MergeSort.', 'QuickSort в среднем случае имеет сложность O(n log n), но в худшем случае (например, при уже отсортированном массиве и наивном выборе опорного элемента) деградирует до O(n²); MergeSort гарантирует O(n log n) в любом случае за счёт стабильного разбиения массива пополам. QuickSort часто предпочитается на практике, потому что: 1) он сортирует ''на месте'' (in-place), требуя O(log n) дополнительной памяти на стек рекурсии против O(n) у MergeSort для временных массивов при слиянии; 2) имеет лучшую локальность обращений к кэшу процессора благодаря работе с непрерывными участками памяти; 3) современные реализации используют рандомизированный или медианный выбор опорного элемента, что делает худший случай крайне маловероятным на практике.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('Frontend', 'Сложно', 'Объясните разницу между Virtual DOM diffing в React и механизмом реактивности на основе Signals (как в новых версиях Angular/Solid), и почему подход через Signals может обеспечивать более точечные (fine-grained) обновления UI без необходимости повторного рендеринга целых компонентов.', 'React использует Virtual DOM: при изменении состояния компонент перерендеривается целиком (создаётся новое виртуальное дерево), затем происходит diffing со старым деревом для вычисления минимального набора реальных DOM-изменений — это требует пересчёта всего поддерева компонента при каждом обновлении, даже если изменилось лишь одно значение. Signals — реактивные примитивы, которые отслеживают конкретные зависимости на уровне отдельных значений: при изменении Signal обновляются только те DOM-узлы или вычисляемые значения, которые непосредственно зависят от него, минуя весь процесс diffing и повторный вызов render-функции компонента, что обеспечивает более точечные и эффективные обновления при частых изменениях мелких данных.');
INSERT OR IGNORE INTO questions (topic, difficulty, question, answer) VALUES ('Desktop', 'Сложно', 'В WPF объясните разницу между DependencyProperty и обычным CLR-свойством с точки зрения поддержки биндинга, стилей и анимации, и почему DependencyProperty хранит своё значение не в самом поле объекта, а через специализированную систему хранения на уровне DependencyObject.', 'Обычное CLR-свойство — это просто геттер/сеттер над приватным полем, не поддерживающее автоматическое уведомление об изменениях, стилизацию через XAML-триггеры или анимацию без дополнительного кода (INotifyPropertyChanged). DependencyProperty регистрируется в статической системе WPF (`DependencyProperty.Register`) и хранит значения в разреженном (sparse) хранилище на уровне `DependencyObject`, что позволяет: 1) эффективно поддерживать value inheritance и multiple value providers (локальное значение, стиль, анимация, тема, значение по умолчанию — с чёткой системой приоритетов); 2) автоматически уведомлять систему привязки данных и анимации об изменениях; хранение через централизованную систему вместо обычного поля экономит память для свойств, которые редко переопределяются (используют значение по умолчанию), поскольку не каждому экземпляру объекта требуется выделенная память под каждое DependencyProperty.');
